// Ported from the Node app's Sequelize model RoomBooking (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class RoomBookingConfiguration : IEntityTypeConfiguration<RoomBooking>
{
    public void Configure(EntityTypeBuilder<RoomBooking> builder)
    {
        builder.ToTable("room_bookings");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.RoomId).HasColumnName("room_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Period).HasColumnName("period");
        builder.Property(e => e.Purpose).HasColumnName("purpose").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.BookedByName).HasColumnName("booked_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasIndex(e => new { e.RoomId, e.Date, e.Period }).IsUnique().HasDatabaseName("uq_room_booking");
        builder.HasOne(e => e.Room).WithMany(p => p.RoomBookings).HasForeignKey(e => e.RoomId).OnDelete(DeleteBehavior.NoAction);
    }
}
